static const char SLR_GEN_HLSL_BLINNPHONGNORMALMAP_TEX[] = "//============================================================================\n""// SlShadersCommon.hlsli —— SLangRender 固化 shader 共享核心\n""//\n""// 提炼自 RenderTest/shader/*.shader（Unity URP）的 HLSL 光照库\n""//（SLangLighting.hlsl），并适配 cvm_render_lib 管线的场景常量约定：\n""//   - PerDraw / LightBlock 两个 std140 cbuffer，成员名与布局和\n""//     RHI 内建着色器（VS_PSCENE / FS_PFLAT / FS_PHONG_*）逐字一致；\n""//   - 2D 伪 3D 光照约定（v3.3/v3.4，GL/GLES/D3D11 三方公式一致）：\n""//     N = normalize(float3(vNrm, 0.75))，V = (0,0,1)，\n""//     直射 L = normalize(float3(uDirDir.xy, 0.6))，\n""//     聚光 L 沿 -toF + 0.6 高度分量（锥角平滑 + 距离平方衰减）。\n""//\n""// 本文件由 build-shaders.ps1 在编译前拼接到每个效果 .hlsl 头部\n""//（glslang 不处理 #include），拼接产物即「d3d11 源码」形态的固化源。\n""//============================================================================\n""\n""// ---- 场景常量（std140；column_major 显式声明，抵消 glslang HLSL 默认\n""//      row_major 的差异——与 GL 内建着色器默认列主序字节级一致）----\n""cbuffer PerDraw : register(b0)\n""{\n""    column_major float4x4 uMVP[64];\n""    float4 uColor[64];\n""    float4 uWMat[128];\n""    float4 uSpec[64];\n""};\n""cbuffer LightBlock : register(b4)\n""{\n""    float4 uAmbient;\n""    float4 uDirColor;\n""    float4 uDirDir;\n""    float4 uSpotColor;\n""    float4 uSpotPosRange;\n""    float4 uSpotDirCos;\n""};\n""\n""// ---- 松散 uniform（按名查找）：glslang 将其收进 _Global 隐式块，\n""//      固化脚本把 _Global 溶解回松散形态（GL/GLES 按名\n""//      glGetUniformLocation(\"uObjIndex\")，与内建着色器一致）----\n""cbuffer PerObj : register(b1) { int uObjIndex; float3 _pad; };\n""\n""// ---- 场景顶点 -> 片元 传递结构（与内建 VS_PSCENE 的 vUv/vWorld/vNrm\n""//      按名链接；固化脚本经 spirv-cross --rename-interface-variable 统一\n""//      命名为 vUv/vWorld/vNrm，可与内建 vert 混搭链接）----\n""struct PSceneV2P\n""{\n""    float2 uv    : TEXCOORD0;\n""    float2 world : TEXCOORD1;\n""    float2 nrm   : TEXCOORD2;\n""};\n""\n""//============================================================================\n""// 光照函数库（提炼自 SLangLighting.hlsl，零 Unity 依赖）\n""//============================================================================\n""\n""//--- 漫反射 ---------------------------------------------------------------\n""\n""float3 DiffuseLambert(float3 albedo, float3 lightColor, float NdotL)\n""{\n""    return albedo * lightColor * saturate(NdotL);\n""}\n""\n""// Half-Lambert（包裹式漫反射，暗部不死黑）\n""float3 DiffuseHalfLambert(float3 albedo, float3 lightColor, float NdotL)\n""{\n""    float wrap = NdotL * 0.5 + 0.5;\n""    return albedo * lightColor * (wrap * wrap);\n""}\n""\n""//--- 高光 -----------------------------------------------------------------\n""\n""// 经典 Phong：R = reflect(-L, N)，R 与 V 越接近高光越强\n""float3 SpecularPhong(float3 lightColor, float3 N, float3 L, float3 V,\n""                     float shininess, float intensity)\n""{\n""    float3 R = reflect(-L, N);\n""    float spec = pow(saturate(dot(R, V)), max(shininess, 1.0));\n""    return lightColor * spec * intensity;\n""}\n""\n""// Blinn-Phong（半 Phong）：H = normalize(L + V)，dot(N, H) 代替 dot(R, V)\n""float3 SpecularBlinnPhong(float3 lightColor, float3 N, float3 L, float3 V,\n""                          float shininess, float intensity)\n""{\n""    float3 H = normalize(L + V);\n""    float spec = pow(saturate(dot(N, H)), max(shininess, 1.0));\n""    return lightColor * spec * intensity;\n""}\n""\n""//--- 边缘 / 菲涅尔 ---------------------------------------------------------\n""\n""float FresnelSchlick(float cosTheta, float f0)\n""{\n""    return f0 + (1.0 - f0) * pow(1.0 - saturate(cosTheta), 5.0);\n""}\n""\n""float3 RimLight(float3 rimColor, float3 N, float3 V, float power, float strength)\n""{\n""    float rim = pow(1.0 - saturate(dot(N, V)), max(power, 0.001));\n""    return rimColor * rim * strength;\n""}\n""\n""//--- 卡通阶梯 -------------------------------------------------------------\n""\n""// steps=3 时得到 0 / 0.5 / 1 三档明暗\n""float ToonRamp(float NdotL, float steps)\n""{\n""    float s = max(steps, 2.0);\n""    float band = floor(saturate(NdotL) * (s - 1.0) + 0.0001);\n""    return saturate(band / (s - 1.0));\n""}\n""\n""// 阶梯边界带一点过渡，feather 建议 0.01 ~ 0.3\n""float ToonRampSmooth(float NdotL, float steps, float feather)\n""{\n""    float s = max(steps, 2.0);\n""    float v = saturate(NdotL) * (s - 1.0);\n""    float band = floor(v);\n""    float f = smoothstep(1.0 - max(feather, 0.001), 1.0, frac(v));\n""    return saturate((band + f) / (s - 1.0));\n""}\n""\n""//============================================================================\n""// 管线场景脚手架（2D 伪 3D 光照，公式与内建着色器逐字一致）\n""//============================================================================\n""\n""// v3.3 基础光照（Lambert 无高光）：环境 + 直射 ndl + 聚光锥角/衰减。\n""// 与 FS_PFLAT/FS_PTEX 公式逐字一致（内建 v3.3 模型）。\n""float3 SceneBaseLight(float2 nrm2, float2 world)\n""{\n""    float3 light = uAmbient.xxx;\n""    if (uDirColor.a > 0.5)\n""        light += uDirColor.rgb * max(dot(nrm2, uDirDir.xy), 0.0);\n""    if (uSpotColor.a > 0.5)\n""    {\n""        float2 toF = world - uSpotPosRange.xy;\n""        float d = length(toF);\n""        float att = clamp(1.0 - d / max(uSpotPosRange.z, 1e-4), 0.0, 1.0);\n""        att *= att;\n""        float ca = dot(toF, uSpotDirCos.xy) / max(d, 1e-4);\n""        float ce = uSpotDirCos.z;\n""        light += uSpotColor.rgb * att * smoothstep(ce, ce + (1.0 - ce) * 0.5, ca);\n""    }\n""    return light;\n""}\n""\n""// 聚光衰减 × 锥角系数（v3.4 Phong 高光的聚光权重复用）\n""float SpotConeAtt(float2 world)\n""{\n""    float2 toF = world - uSpotPosRange.xy;\n""    float d = length(toF);\n""    float att = clamp(1.0 - d / max(uSpotPosRange.z, 1e-4), 0.0, 1.0);\n""    att *= att;\n""    float ca = dot(toF, uSpotDirCos.xy) / max(d, 1e-4);\n""    float ce = uSpotDirCos.z;\n""    return att * smoothstep(ce, ce + (1.0 - ce) * 0.5, ca);\n""}\n""\n""//============================================================================\n""// SlBlinnPhongNormalMap.hlsl —— Blinn-Phong + 法线扰动\n""// 提炼自 RenderTest/shader/BlinnPhongNormalMap.shader（Unity URP），零 Unity 依赖。\n""//\n""// Unity 原型：法线贴图解码（BC5 / RGB 两轨）→ 切线空间扰动\n""//   worldToTangent = float3x3(T, B, N)（行主序），逐光转切线空间着色。\n""// 2D 管线映射（单纹理契约）：无独立法线贴图通道，从 albedo 亮度推高度，\n""//   经屏幕空间导数 ddx/ddy 差分得凹凸向量扰动伪 3D 法线 N.xy：\n""//     bump = (hC - hX, hC - hY) * bumpScale（hC/hX/hY = 当前/右邻/下邻亮度）\n""//   高光与边缘光用扰动后 N；漫反射沿用内建 v3.3 基座（2D ndl）。\n""//   flat 变体无纹理 → 无高度 → 无扰动（退化为 BlinnPhong flat 形态）。\n""//\n""// uSpec[uObjIndex] 分量语义（xy 同 BlinnPhong）：\n""//   .x = 高光强度   .y = 光泽度（shininess）\n""//   .z = 凹凸强度（bumpScale）   .w = 边缘光强度（幂固定 3.0 = Unity 默认）\n""//\n""// 变体契约 / 重新生成：同 SlLambert.hlsl 头注释。\n""//============================================================================\n""\n""struct SlVsIn\n""{\n""    float2 pos : POSITION;\n""    float2 uv  : TEXCOORD0;\n""};\n""\n""struct SlPsIn\n""{\n""    float4 pos   : SV_POSITION;\n""    float2 uv    : TEXCOORD0;\n""    float2 world : TEXCOORD1;\n""    float2 nrm   : TEXCOORD2;\n""};\n""\n""#ifndef SL_FLAT\n""Texture2D    uTex     : register(t0);\n""SamplerState uSampler : register(s0);\n""\n""float SlLuma(float3 c) { return dot(c, float3(0.299, 0.587, 0.114)); }\n""#endif\n""\n""// 场景顶点：与内建 VS_PSCENE 数学逐字一致（PerDraw 布局见共享核心）\n""SlPsIn vert(SlVsIn i)\n""{\n""    SlPsIn o;\n""    o.uv = i.uv;\n""    int k = uObjIndex * 2;\n""    o.world = float2(dot(i.pos, uWMat[k].xy), dot(i.pos, uWMat[k].zw))\n""              + uWMat[k + 1].xy;\n""    o.nrm = uWMat[k + 1].zw;\n""    o.pos = mul(uMVP[uObjIndex], float4(i.pos, 0.0, 1.0));\n""    return o;\n""}\n""\n""// Blinn-Phong + 亮度凹凸扰动（伪 3D 法线家族）\n""float4 frag(SlPsIn i) : SV_Target\n""{\n""#ifdef SL_FLAT\n""    float4 base = uColor[uObjIndex];\n""    float2 nrmB = i.nrm;              // flat：无高度场，不扰动\n""#else\n""    float4 base = uColor[uObjIndex] * uTex.Sample(uSampler, i.uv);\n""    // 高度差分（右邻/下邻取自屏幕空间导数偏移，均匀控制流内安全）\n""    float hC = SlLuma(uTex.Sample(uSampler, i.uv).rgb);\n""    float hX = SlLuma(uTex.Sample(uSampler, i.uv + ddx(i.uv)).rgb);\n""    float hY = SlLuma(uTex.Sample(uSampler, i.uv + ddy(i.uv)).rgb);\n""    float2 nrmB = i.nrm + (float2(hC - hX, hC - hY)\n""                            * uSpec[uObjIndex].z);\n""#endif\n""    float3 light = SceneBaseLight(i.nrm, i.world);\n""\n""    float3 N = normalize(float3(nrmB, 0.75));\n""    float3 V = float3(0.0, 0.0, 1.0);\n""    float4 sp = uSpec[uObjIndex];\n""    float shin = max(sp.y, 0.001);\n""\n""    if (uDirColor.a > 0.5)\n""    {\n""        float3 L = normalize(float3(uDirDir.xy, 0.6));\n""        float ndl = dot(N, L);\n""        if (ndl > 0.0)   // Unity：step(0, NdotL) 门控高光\n""        {\n""            float3 H = normalize(L + V);\n""            light += uDirColor.rgb * pow(max(dot(N, H), 0.0), shin) * sp.x;\n""        }\n""    }\n""    if (uSpotColor.a > 0.5)\n""    {\n""        float cone = SpotConeAtt(i.world);\n""        float2 toF = i.world - uSpotPosRange.xy;\n""        float d = length(toF);\n""        float3 L2 = normalize(float3(-toF / max(d, 1e-4), 0.6));\n""        if (dot(N, L2) > 0.0)\n""        {\n""            float3 H2 = normalize(L2 + V);\n""            light += uSpotColor.rgb * cone\n""                      * pow(max(dot(N, H2), 0.0), shin) * sp.x;\n""        }\n""    }\n""\n""    // 菲涅尔加权边缘光（幂固定 Unity 默认 3）\n""    if (sp.w > 0.0)\n""    {\n""        float3 rimColor = float3(0.35, 0.70, 1.00);\n""        float fres = FresnelSchlick(saturate(dot(N, V)), 0.04);\n""        float rim = pow(1.0 - saturate(dot(N, V)), 3.0);\n""        light += rimColor * (rim * sp.w) * (0.5 + 0.5 * fres);\n""    }\n""    return float4(base.rgb * light, base.a);\n""}\n";
